function ensureDemigodVisible() {
  try {
    document.body.style.setProperty('background', '#0A0A0A', 'important');
    document.body.style.setProperty('color', '#f5f0e6', 'important');
    ['#dg-live-roles', '#demigod-trust-block', '#demigod-pricing', '.hero-section', 'main > *', 'body'].forEach(function(sel) {
      var els = document.querySelectorAll(sel);
      els.forEach(function(el) {
        if (el) {
          el.style.setProperty('display', '', 'important');
          el.style.setProperty('visibility', 'visible', 'important');
          el.style.setProperty('opacity', '1', 'important');
        }
      });
    });
    // create if missing to prevent white
    if (!q('#demigod-trust-block')) {
      var t = document.createElement('section');
      t.id = 'demigod-trust-block';
      t.style.cssText = 'display:block !important; visibility:visible !important;';
      document.body.appendChild(t);
    }
    if (!q('#dg-live-roles')) {
      var s = document.createElement('section');
      s.id = 'dg-live-roles';
      s.style.cssText = 'padding:2rem 1rem;max-width:52rem;margin:0 auto; display:block !important; visibility:visible !important;';
      var trust = q('#demigod-trust-block');
      if (trust && trust.parentNode) trust.parentNode.insertBefore(s, trust.nextSibling);
      else document.body.appendChild(s);
    }
  } catch(e) {}
}
